import{_ as a,o as s,c as t,a0 as o}from"./chunks/framework.BGyYNsHo.js";const S=JSON.parse('{"title":"Data Formats","description":"","frontmatter":{},"headers":[],"relativePath":"reference/05-data-formats.md","filePath":"reference/05-data-formats.md"}'),n={name:"reference/05-data-formats.md"};function r(d,e,i,c,p,l){return s(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="data-formats" tabindex="-1">Data Formats <a class="header-anchor" href="#data-formats" aria-label="Permalink to &quot;Data Formats&quot;">​</a></h1><p>The three data formats the app reads and writes: the project file, the INP dialect, and the <code>.out</code> binary.</p><h2 id="project-file-oswmm-json" tabindex="-1">Project file (<code>.oswmm.json</code>) <a class="header-anchor" href="#project-file-oswmm-json" aria-label="Permalink to &quot;Project file (\`.oswmm.json\`)&quot;">​</a></h2><p>The JSON produced by <code>Net.serialize()</code> (<code>network.js:465-488</code>) — a full snapshot of <code>{title, units, options, nodes, links, subcatchments, timeseries, curves, lidControls, lidUsages, pollutants, landUses, treatments, aquifers, snowpacks, snowpackAssignments, rawSections, …}</code>. This is what <strong>Save</strong> writes and <strong>Load</strong> reads.</p><h2 id="inp-dialect-standard-swmm" tabindex="-1">INP dialect (standard SWMM) <a class="header-anchor" href="#inp-dialect-standard-swmm" aria-label="Permalink to &quot;INP dialect (standard SWMM)&quot;">​</a></h2><p>Written by <code>inpExporter.generateInp</code> (<code>inpExporter.js:7-715</code>) in a stable section order:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[TITLE] [OPTIONS] [EVAPORATION] [RAINGAGES] [RDII_DECAY]</span></span>
<span class="line"><span>[SUBCATCHMENTS] [SUBAREAS] [INFILTRATION]</span></span>
<span class="line"><span>[JUNCTIONS] [OUTFALLS] [STORAGE] [DIVIDERS]</span></span>
<span class="line"><span>[CONDUITS] [LOSSES] [PUMPS] [WEIRS] [ORIFICES] [OUTLETS] [XSECTIONS]</span></span>
<span class="line"><span>[TIMESERIES] [TAGS] [REPORT]</span></span>
<span class="line"><span>[COORDINATES] [VERTICES] [POLYGONS] [SYMBOLS]</span></span>
<span class="line"><span>[CURVES] [LID_CONTROLS] [LID_USAGE] [POLLUTANTS] [LANDUSES] [BUILDUP] [WASHOFF]</span></span>
<span class="line"><span>[TREATMENT] [AQUIFERS] [GROUNDWATER] [SNOWPACKS] [SNOWPACK_ASSIGNMENT]</span></span>
<span class="line"><span>+ any unrecognized rawSections re-emitted verbatim (inpExporter.js:696-712)</span></span></code></pre></div><p>Key export behaviors: option precedence UI value → <code>opt.raw</code> → default (<code>inpExporter.js:47-50</code>); <code>REPORT_STEP</code> heuristic from imported value → first gage interval → 1 h (<code>:54-69</code>); OUTFALL column-shift for stage types (<code>:207-215</code>); WEIR ROADWAY handling (<code>:287-295</code>); <code>REPORT</code> whitelist (<code>:390-403</code>).</p><p>The parser (<code>inpParser.js:7-29</code>) is <strong>lossless</strong>: every section is kept tokenized (<code>sections</code>) <em>and</em> raw (<code>rawSections</code>), so anything the UI can&#39;t edit survives export.</p><h2 id="out-binary-format-swmm-output" tabindex="-1"><code>.out</code> binary format (SWMM output) <a class="header-anchor" href="#out-binary-format-swmm-output" aria-label="Permalink to &quot;\`.out\` binary format (SWMM output)&quot;">​</a></h2><p>Parsed by <code>swmmOutParser.js</code>: footer magic <code>516114522</code>, version/flow-units header, length-prefixed ID name tables, variable counts per object class, and per-period Float32 records for subcatchments (8 vars), nodes (6), links (5), and system (14). Exposed as zero-copy typed-array views.</p><p>Footer layout: the last six INT32s are <code>idNamesOffset, objPropsOffset, resultsOffset, numPeriods, errCode, magicEnd</code>; the magic value <code>516114522</code> is validated. Hot paths: <code>getTimeSeries(type,index,varIndex)</code> (cached) and <code>getStepData(type,step,varIndex)</code> for per-step map coloring.</p>`,12)])])}const h=a(n,[["render",r]]);export{S as __pageData,h as default};
